    out.unlockable_matches += n * plan.unlockable;
    for (const q of plan.questions) {
      const agg = byQ.get(q) ?? byQ.set(q, { id: q, label: QUESTION_BY_ID[q].label, users: 0, unlockable: 0 }).get(q);
